#!/usr/bin/env node
/**
 * PreToolUse hook: denies direct Write/Edit/MultiEdit edits to the files a
 * KB bundle's write path (kb_write, kb_supersede, ...) generates and owns —
 * INDEX.md, log.jsonl, and the search index, directly inside the bundle
 * root. Hand-editing one only creates drift: the next store write
 * recomputes and overwrites it, silently dropping whatever the edit
 * changed. A same-named file *nested* under the bundle (a record someone
 * chose to call `notes/INDEX.md`, say) is not store-owned and is left
 * alone — only the exact generated file the store itself writes is denied.
 *
 * Independent of STRAUSS_KB_NO_VALIDATE_HOOK — that variable names the
 * *validate* hook specifically, and this check is a different kind of
 * cheap: one basename comparison against a fixed set, no CLI shelled out,
 * nothing worth an opt-out for cost. A project that genuinely needs to
 * hand-edit a generated file disables this hook the ordinary way (Claude
 * Code's own hook settings), not through that env var.
 *
 * Fails open: any unexpected input or error allows the tool call through
 * untouched, same as the rest of this plugin's hooks — this only ever
 * *adds* a deny decision, never removes the normal permission flow.
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { findBundleRoot, isStoreOwnedFile } from "./kb-bundle.mjs";

// A broken pipe (the hook harness closing stdout early) must not crash the
// process — Node emits it asynchronously on the stream, past any try/catch.
process.stdout.on("error", () => {});

function main() {
  let input;
  try {
    input = JSON.parse(readFileSync(0, "utf8"));
  } catch {
    return 0;
  }

  const filePath = input?.tool_input?.file_path;
  if (typeof filePath !== "string" || !filePath) return 0;

  const cwd =
    typeof input?.cwd === "string" && input.cwd ? input.cwd : process.cwd();
  // Unconditional: normalizes native separators and collapses `..` in one
  // call, whether or not `filePath` was already absolute (path.resolve
  // ignores `cwd` once it hits an absolute argument) — see
  // validate-kb-bundle.mjs's identical call for why a conditional here
  // used to be a bug.
  const absolute = resolve(cwd, filePath);

  const bundleRoot = findBundleRoot(absolute);
  if (!bundleRoot) return 0;

  // Only the bundle root's own generated files are store-owned. Without
  // this, a legitimately-authored record several directories deeper that
  // happens to share a basename with one of them (`notes/INDEX.md`) would
  // be denied too.
  if (dirname(absolute) !== bundleRoot) return 0;
  if (!isStoreOwnedFile(absolute)) return 0;

  const name = absolute.slice(bundleRoot.length).replace(/^[\\/]+/, "");

  process.stdout.write(
    JSON.stringify({
      hookSpecificOutput: {
        hookEventName: "PreToolUse",
        permissionDecision: "deny",
        permissionDecisionReason: `${name} is generated by the KB store and will be overwritten — edit the underlying record instead.`,
      },
    }),
  );
  return 0;
}

function safeMain() {
  try {
    return main();
  } catch {
    return 0;
  }
}

process.exit(safeMain());
